import { areaNotFound } from "./areaResources";
import { MAX_BATCH_VALUES } from "./batchValidation";
import { matchManifest, matchReportResponse } from "./matchReport";
import { readPostedRows } from "./requestRows";
import { invalidQuery, type ApiResponse } from "./routeResponse";
import type { RouteRequest } from "./routing";
import { choices, readChoice } from "./queryParameters";
import { QUERY_RULES } from "./queryRules";

const VALIDATE = QUERY_RULES["GET /areas:validate"];

/**
 * Validate many area codes or names against one published boundary release.
 * A GET carries them as repeated value=, up to what a URL holds; a POST
 * carries a whole column in its body, as JSON or CSV.
 */
export const handleAreaValidationRoutes = ({
	context,
	releaseId,
	parsedUrl,
	segments,
	method,
	body: requestBody,
}: RouteRequest): ApiResponse | undefined => {
	if (
		segments.length !== 2 ||
		segments[0] !== "v1" ||
		segments[1] !== "areas:validate"
	)
		return undefined;
	const geographyResolver = context.geographyResolver;
	const geography = parsedUrl.searchParams.get("geography");
	const boundaryRelease = parsedUrl.searchParams.get("release");
	const posted =
		method === "POST"
			? readPostedRows(requestBody, { withValues: false })
			: undefined;
	if (posted && "status" in posted) return posted;
	const values = posted
		? posted.areas
		: parsedUrl.searchParams.getAll("value");
	const parents = posted
		? (posted.parents ?? [])
		: parsedUrl.searchParams.getAll("parent");
	const format = readChoice(
		parsedUrl.searchParams.get("format"),
		VALIDATE.format,
	);
	if (!format)
		return invalidQuery(`format must be ${choices(VALIDATE.format)}.`);
	if (Boolean(geography) !== Boolean(boundaryRelease))
		return invalidQuery(
			"geography and release must be supplied together, or both omitted to infer a likely compiled release.",
		);
	if (values.length === 0)
		return invalidQuery(
			"Supply at least one value to validate, as value=; it may be repeated.",
		);
	// The body's own limit was checked as it was read.
	if (!posted && values.length > MAX_BATCH_VALUES)
		return invalidQuery(
			`At most ${MAX_BATCH_VALUES} values can be validated in one GET; this one has ${values.length}. POST the column as JSON or CSV to send more.`,
		);
	if (parents.length > 0 && parents.length !== values.length)
		return invalidQuery(
			"parent, when supplied, must occur once for every value in the same input order.",
		);
	if (!geography || !boundaryRelease) {
		const unavailable = geographyResolver.requires("areas");
		if (unavailable) return unavailable;
		const matched = geographyResolver.matchAreaValues(
			values,
			parents.length > 0 ? parents : undefined,
		);
		const manifest = matchManifest(
			releaseId,
			values,
			parents.length > 0 ? parents : undefined,
			matched,
		);
		const body = {
			...matched,
			manifest,
			note: "likely is the compiled geography/release with the most exact resolutions; where others resolve exactly as many, it is the newest of them and tiedWith lists the rest, since the values alone do not tell them apart. It is not an automatic join or conversion: mixed-code-systems and incomplete input remain unjoinable, and recommendations are published paths only. A parent resolves a shared name only when one published containment relationship matches it.",
		};
		return matchReportResponse(releaseId, format, manifest, body);
	}
	const validated = geographyResolver.validateAreas(
		geography,
		boundaryRelease,
		values,
		parents.length > 0 ? parents : undefined,
	);
	if (!validated) return areaNotFound(context, geography, boundaryRelease);
	const matched = {
		likely: {
			geography,
			boundaryRelease,
			resolved: validated.values.filter(
				(value) =>
					value.status === "valid" || value.status === "matched",
			).length,
		},
		candidates: [],
		values: validated.values,
		verdict: validated.summary.joinable ? "joinable" : "incomplete",
		recommendations: [],
	};
	const manifest = matchManifest(
		releaseId,
		values,
		parents.length > 0 ? parents : undefined,
		matched,
	);
	const body = {
		geography,
		boundaryRelease,
		summary: validated.summary,
		values: validated.values,
		manifest,
		note: 'Codes are checked against this exact release; one it does not hold says whether other releases or geographies do. Names match only exactly, through a published alias, or with an administrative title such as "City of" set aside, and a name meaning several areas lists them all rather than choosing. Anything trimmed or re-cased to read a value is listed in normalised. joinable is true only when every value names exactly one area of this release.',
	};
	return matchReportResponse(releaseId, format, manifest, body);
};
